        modelBuilder
            .HasDefaultSchema("PRDB")
            .UseCollation("USING_NLS_COMP");

        modelBuilder.Entity<Adord2pc>(entity =>
        {
            entity.HasKey(e => new { e.Meid, e.Mecreator, e.Mesid, e.Source, e.Thickhead });

            entity.ToTable("ADORD2PC");

            entity.Property(e => e.Meid)
                .HasPrecision(10)
                .HasDefaultValueSql("1 ")
                .HasColumnName("MEID");
            entity.Property(e => e.Mecreator)
                .HasMaxLength(2)
                .IsUnicode(false)
                .HasDefaultValueSql("'' ")
                .HasColumnName("MECREATOR");
            entity.Property(e => e.Mesid)
                .HasPrecision(5)
                .HasDefaultValueSql("1 ")
                .HasColumnName("MESID");
            entity.Property(e => e.Source)
                .HasMaxLength(2)
                .IsUnicode(false)
                .HasDefaultValueSql("'-' ")
                .HasColumnName("SOURCE");
            entity.Property(e => e.Thickhead)
                .HasPrecision(5)
                .HasDefaultValueSql("0 ")
                .HasColumnName("THICKHEAD");
            entity.Property(e => e.Hexit)
                .HasDefaultValueSql("null\n")
                .HasColumnName("HEXIT");
            entity.Property(e => e.Mop)
                .HasMaxLength(120)
                .IsUnicode(false)
                .ValueGeneratedOnAdd()
                .HasDefaultValueSql("null\n")
                .HasColumnName("MOP");
            entity.Property(e => e.Profile)
                .HasDefaultValueSql("null\n")
                .HasColumnName("PROFILE");
            entity.Property(e => e.Toc)
                .ValueGeneratedOnAdd()
                .HasDefaultValueSql("null\n")
