                .HasColumnType("DATE")
                .HasColumnName("TOM");
            entity.Property(e => e.Wexit)
                .HasDefaultValueSql("null\n")
                .HasColumnName("WEXIT");

            entity.HasOne(d => d.Me1).WithMany(p => p.Adord2pcs)
                .HasForeignKey(d => new { d.Meid, d.Mecreator, d.Mesid })
                .HasConstraintName("FK_ADORD2PC");
        });

